examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
    // Directly above the field, so it sits above the keyboard with the field's imePadding.
    MonarchSlashMenu(
        query = query,
        items = commands,
        onSelect = { item ->
            if (query != null) value = query.replacing(value, markdown[item.id].orEmpty())
        },
        groupOrder = listOf({{groups.0}}, {{groups.1}}, {{groups.2}}),
    )
    MonarchTextField(
        value = value,
        onValueChange = { value = it },
        modifier = Modifier.fillMaxWidth(),
        label = {{field.label}},
        placeholder = {{field.placeholder}},
        singleLine = false,
    )
}

